import{_ as e,o as s,c as n,a2 as t}from"./chunks/framework.CqGS6Fr9.js";const m=JSON.parse('{"title":"CLI reference","description":"","frontmatter":{"pageId":"admins/cli","contentRevision":6},"headers":[],"relativePath":"en/admins/cli.md","filePath":"en/admins/cli.md"}'),l={name:"en/admins/cli.md"};function p(r,a,i,o,c,d){return s(),n("div",null,[...a[0]||(a[0]=[t(`<h1 id="cli-reference" tabindex="-1">CLI reference <a class="header-anchor" href="#cli-reference" aria-label="Permalink to &quot;CLI reference&quot;">​</a></h1><p>Applies to: Rimlink 0.9.2 · RimWorld 1.7 · protocol 1.</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage {#usage}&quot;">​</a></h2><p>rimlink-tools has four roots: backup, restore, modpack and admin. Local backup/restore operates on disk; admin and modpack publication operations contact the server.</p><p>Read-only example: <code>rimlink-tools admin status --server https://play.example.org:25560 --token &lt;TOKEN&gt;</code>. Tokens in arguments can appear in shell history and process listings: never save a real-secret command in tickets or screenshots. --insecure trusts an unverified certificate and is suitable only for isolated tests.</p><p>Use the appropriate root&#39;s --help for exact arity. Every admin command is listed below; modpack and disk backup commands are explained in the linked guides. IDs are numeric; CLI decimal parsing uses invariant culture (a dot).</p><h2 id="cli-read-first" tabindex="-1">A safe first CLI session <a class="header-anchor" href="#cli-read-first" aria-label="Permalink to &quot;A safe first CLI session {#cli-read-first}&quot;">​</a></h2><p>Inspect --help, HTTPS endpoint and certificate trust. Remote admin commands require --server and --token; local backup/restore use --data without HTTP. Read status/players, resolve a persistent playerId, then inspect player/actions before mutating.</p><p>For example, admin status → admin players → admin player 42 → admin actions is read-only. Supply operator address/secrets outside shared chat. Wallet delta is required despite ambiguous help brackets; negative values debit funds. Never test syntax with a real compensation.</p><p>The groups below retain all commands. Before an irreversible operation record target, reason, backup and expected result, then verify response/audit.</p><h2 id="limits" tabindex="-1">Limits and safety <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits and safety {#limits}&quot;">​</a></h2><p>The current wallet command requires a delta despite the short help describing it as optional: read balances through GET economy/wallet/{id} or player details. raids cancel supports --return for returning pawns. A CLI/HTTP error does not prove an operation had no effect: inspect state before retrying.</p><h2 id="related" tabindex="-1">See also <a class="header-anchor" href="#related" aria-label="Permalink to &quot;See also {#related}&quot;">​</a></h2><ul><li><a href="./api">REST API reference</a></li><li><a href="./modpacks">Managing modpacks</a></li><li><a href="./backup-recovery">Backup and recovery</a></li></ul><h2 id="reference" tabindex="-1">All admin commands <a class="header-anchor" href="#reference" aria-label="Permalink to &quot;All admin commands {#reference}&quot;">​</a></h2><p>Each line follows <code>rimlink-tools admin</code>; <code>--server URL --token TOKEN</code> is required, <code>--insecure</code> is optional for tests only. <code>&lt;...&gt;</code> is required, <code>[...]</code> optional, <code>|</code> a choice. Quote multi-word reasons. Permissions and effects match the corresponding REST operation; the API table gives minimum scopes.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>actions</span></span>
<span class="line"><span>archive &lt;playerId&gt;</span></span>
<span class="line"><span>archived [archived|restored|all]</span></span>
<span class="line"><span>auction cancel &lt;id&gt; [reason]</span></span>
<span class="line"><span>auctions</span></span>
<span class="line"><span>backup</span></span>
<span class="line"><span>backup-get &lt;name&gt; &lt;file&gt;</span></span>
<span class="line"><span>backups</span></span>
<span class="line"><span>ban &lt;playerId&gt; [days] [reason]</span></span>
<span class="line"><span>bans</span></span>
<span class="line"><span>broadcast &lt;text&gt;</span></span>
<span class="line"><span>chat [playerId]</span></span>
<span class="line"><span>colonies [playerId]</span></span>
<span class="line"><span>colony revoke &lt;ownerPlayerId&gt; &lt;memberPlayerId&gt;</span></span>
<span class="line"><span>config</span></span>
<span class="line"><span>economy freeze [reason]|unfreeze|stats</span></span>
<span class="line"><span>forbid list|add &lt;def...&gt;|remove &lt;def...&gt;</span></span>
<span class="line"><span>incidents list [playerId]|cancel &lt;id&gt; [reason]</span></span>
<span class="line"><span>influence</span></span>
<span class="line"><span>influence-archive-disable &lt;archiveId&gt; &lt;settlementId&gt; &lt;requestId&gt; &lt;worldId&gt; &lt;generation&gt; &lt;allianceId&gt; &lt;version&gt;</span></span>
<span class="line"><span>influence-archive-setting &lt;archiveId&gt;</span></span>
<span class="line"><span>influence-color &lt;allianceId&gt; &lt;worldId&gt; &lt;paletteIndex&gt; &lt;requestId&gt;</span></span>
<span class="line"><span>influence-disable &lt;settlementId&gt; &lt;requestId&gt; &lt;worldId&gt; &lt;generation&gt; &lt;allianceId&gt; &lt;version&gt;</span></span>
<span class="line"><span>influence-setting &lt;settlementId&gt;</span></span>
<span class="line"><span>kick &lt;playerId&gt; [reason]</span></span>
<span class="line"><span>live list [playerId]|end &lt;id&gt; [reason]</span></span>
<span class="line"><span>lots [playerId]</span></span>
<span class="line"><span>modpack</span></span>
<span class="line"><span>mute &lt;playerId&gt; &lt;minutes&gt;</span></span>
<span class="line"><span>online</span></span>
<span class="line"><span>parcels &lt;playerId&gt;</span></span>
<span class="line"><span>pardon &lt;banId&gt;</span></span>
<span class="line"><span>peaceful &lt;playerId&gt; on|off</span></span>
<span class="line"><span>player &lt;playerId&gt;</span></span>
<span class="line"><span>player-freeze &lt;playerId&gt; [reason]</span></span>
<span class="line"><span>player-unfreeze &lt;playerId&gt;</span></span>
<span class="line"><span>players [query]</span></span>
<span class="line"><span>procurement list [page]|cancel &lt;id&gt; [reason]</span></span>
<span class="line"><span>raids list [playerId]|cancel &lt;id&gt; [reason] [--return]|freeze [reason]|unfreeze|stats</span></span>
<span class="line"><span>recreateworld</span></span>
<span class="line"><span>refund lot|parcel &lt;id&gt;</span></span>
<span class="line"><span>removals &lt;playerId&gt;</span></span>
<span class="line"><span>rename &lt;playerId&gt; &lt;name&gt; [faction]</span></span>
<span class="line"><span>reset &lt;playerId&gt;</span></span>
<span class="line"><span>restore-colony &lt;archiveId&gt;</span></span>
<span class="line"><span>role &lt;playerId&gt; player|moderator|admin</span></span>
<span class="line"><span>rollback &lt;playerId&gt; &lt;version&gt;</span></span>
<span class="line"><span>saveall</span></span>
<span class="line"><span>saves &lt;playerId&gt;</span></span>
<span class="line"><span>say &lt;author&gt; &lt;text&gt;</span></span>
<span class="line"><span>shop &lt;playerId&gt;</span></span>
<span class="line"><span>shutdown &lt;seconds&gt; [reason]</span></span>
<span class="line"><span>status</span></span>
<span class="line"><span>trade cancel &lt;id&gt; [reason]</span></span>
<span class="line"><span>trades [playerId]</span></span>
<span class="line"><span>unmute &lt;playerId&gt;</span></span>
<span class="line"><span>wallet &lt;playerId&gt; &lt;+n|-n&gt; [reason]</span></span></code></pre></div><p><code>wallet</code> requires delta: despite brackets in current --help, omitting it is not a balance query. <code>raids cancel --return</code> requests pawn return; it is not arbitrary compensation. Read an influence setting first: requestId and context/version prevent unsafe retries and stale intent. <code>reset</code>, <code>recreateworld</code>, rollback and restore change/destroy data: back up and obtain confirmation first.</p><h3 id="local-commands-and-modpack" tabindex="-1">Local commands and modpack <a class="header-anchor" href="#local-commands-and-modpack" aria-label="Permalink to &quot;Local commands and modpack&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>rimlink-tools backup --data &lt;dir&gt; [--out &lt;archive.tar.zst&gt;]</span></span>
<span class="line"><span>rimlink-tools restore --data &lt;dir&gt; --from &lt;archive.tar.zst&gt;</span></span>
<span class="line"><span>rimlink-tools modpack import --from &lt;ModsConfig.xml&gt; [--mods-dir &lt;folders...&gt;] [--dry-run]</span></span>
<span class="line"><span>rimlink-tools modpack defs --mods-dir &lt;folders...&gt; [--dry-run]</span></span>
<span class="line"><span>rimlink-tools modpack configs import --config-dir &lt;dir&gt; --mods-dir &lt;folders...&gt; --mod &lt;packageIds...&gt; [--dry-run]</span></span>
<span class="line"><span>rimlink-tools modpack configs import --clear [--dry-run]</span></span>
<span class="line"><span>rimlink-tools modpack configs list --server &lt;URL&gt; --token &lt;TOKEN&gt;</span></span>
<span class="line"><span>rimlink-tools modpack package requirements --output &lt;new-file&gt; --server &lt;URL&gt; --token &lt;TOKEN&gt;</span></span>
<span class="line"><span>rimlink-tools modpack package pack --source &lt;prepared-dir&gt; --requirements &lt;file&gt; --output &lt;new-dir&gt;</span></span>
<span class="line"><span>rimlink-tools modpack package publish --from &lt;dir&gt; --confirm-redistribution [--confirm-public] [--confirm-shared-settings] --server &lt;URL&gt; --token &lt;TOKEN&gt;</span></span>
<span class="line"><span>rimlink-tools modpack package status --server &lt;URL&gt; --token &lt;TOKEN&gt;</span></span>
<span class="line"><span>rimlink-tools modpack package unpublish --server &lt;URL&gt; --token &lt;TOKEN&gt;</span></span></code></pre></div><p>Without --dry-run, import/defs/configs import require --server/--token; HTTP commands support --insecure. Backup is safe while running; restore requires a stopped server. Pack is offline and uses a separately prepared redistributable collection, never the game root; output paths must be new. configs import shares selected mods below Rimlink: inspect files for secrets. requirements/status read the server; publish/unpublish change package availability and consent flags must not be supplied automatically.</p><h3 id="outposts-pending" tabindex="-1">Outposts (Pending) <a class="header-anchor" href="#outposts-pending" aria-label="Permalink to &quot;Outposts (Pending)&quot;">​</a></h3><p><code>outposts inspect [--player ID] [--operation ID] [--limit N] [--cursor VALUE]</code></p><p><code>outposts preview|initialize|activate-domain-format|resolve --request FILE</code></p><p><code>outposts manifest inspect ID|upload FILE|confirm --request FILE</code></p><p>These are remote REST commands. Retain the original command and explicitly set confirmed=true after review. The CLI does not silently re-preview/retry or open a running database. See the <a href="./passive-outposts">guide</a> for bounds and recovery.</p>`,26)])])}const g=e(l,[["render",p]]);export{m as __pageData,g as default};
